//! Preserve each driver's SDK timer and normalize its output afterward.
use serde_json::Value;use std::{fs,path::Path,process::{Command,Stdio}};
fn snapshot_after_latency(){
 if std::env::var_os("ZOPRO_BENCH_PERF_CTL").is_none(){return;}
 let path=std::env::var("ZOPRO_GS_AFTER_LATENCY").unwrap();
 match fs::OpenOptions::new().write(true).create_new(true).open(path){
  Ok(file)=>{let mut state=std::collections::BTreeMap::new();for p in ["/proc/loadavg","/proc/swaps","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/memory.max","/sys/fs/cgroup/memory.current","/sys/fs/cgroup/memory.peak","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.current","/sys/fs/cgroup/memory.swap.events","/sys/fs/cgroup/memory.swap.max"]{if let Ok(s)=fs::read_to_string(p){state.insert(p,s);}}serde_json::to_writer_pretty(file,&state).unwrap();},
  Err(e)if e.kind()==std::io::ErrorKind::AlreadyExists=>{},Err(e)=>panic!("stage snapshot failed: {e}")
 }
}
fn main(){snapshot_after_latency();let a:Vec<_>=std::env::args_os().collect();assert_eq!(a.len(),5);let engine=std::env::var("ZOPRO_GS_ENGINE").unwrap();let dir=Path::new(&a[4]);fs::create_dir_all(dir).unwrap();let workers=std::env::var("RAYON_NUM_THREADS").unwrap();let mut child=if engine=="aeglos"{let stem=Path::new(&a[1]).file_stem().unwrap().to_str().unwrap();let mut c=Command::new("/usr/local/bin/aeglos-ablation");c.args(["aeglos",&format!("/gnark-keys/{stem}.key")]).args([&a[2],&a[3]]);c.env("ZOPRO_BENCH_PROOFS",dir.parent().unwrap()).env("AEGLOS_BENCH_DISABLE_SHIFTED","0").env("AEGLOS_CPU_THREADS",&workers).env("GOMAXPROCS",&workers);for(from,to)in[("ZOPRO_BENCH_PERF_CTL","CROSS_PERF_CTL"),("ZOPRO_BENCH_PERF_ACK","CROSS_PERF_ACK")]{if let Some(v)=std::env::var_os(from){c.env(to,v);}}c}else{assert!(matches!(engine.as_str(),"accepted"|"off"|"on"));let mut c=Command::new(if engine=="accepted"{"/usr/local/bin/gs-accepted"}else{"/usr/local/bin/gs-candidate"});c.args(&a[1..]).env("ZOPRO_CPU_G2_PREFIX_TREE",if engine=="on"{"1"}else{"0"});c};child.stdout(Stdio::from(fs::File::create(dir.join("driver.stdout")).unwrap())).stderr(Stdio::from(fs::File::create(dir.join("driver.stderr")).unwrap()));assert!(child.status().unwrap().success(),"SDK failed");let output=fs::read_to_string(dir.join("driver.stdout")).unwrap();let mut samples=0;let mut summaries=0;let rounds=a[3].to_str().unwrap().parse::<usize>().unwrap();
 for line in output.lines(){if let Some(s)=line.strip_prefix("SAMPLE "){let mut v:Value=serde_json::from_str(s).unwrap();if engine=="aeglos"{assert_eq!(v["cache_hit"],true);v["ms"]=v["verified_ms"].clone();}assert_eq!(v["round"].as_u64().unwrap(),samples);println!("SAMPLE {v}");samples+=1;}else if let Some(s)=line.strip_prefix("SUMMARY "){let mut v:Value=serde_json::from_str(s).unwrap();let n=workers.parse::<u64>().unwrap();if engine=="aeglos"{assert_eq!(v["threads"].as_u64().unwrap(),n);v["workers"]=n.into();}else{assert_eq!(v["workers"].as_u64().unwrap(),n);assert_eq!(v["priming"],3);}assert_eq!(v["rounds"].as_u64().unwrap(),rounds as u64);println!("SUMMARY {v}");summaries+=1;}}assert_eq!(samples,rounds as u64);assert_eq!(summaries,1);}
